From 321ea0cb7d7e59a85d088da1de4310566b5b5941 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Wed, 25 Nov 2026 22:22:23 +0100
Subject: [PATCH] applets/systemtray: add a menu to set the visibility of all
 entries

Making the tray small meant changing every entry to "Show only in popup"
one by one, as only "Always show all" works on all of them. A "Set All
To" menu now changes every entry at once, leaving disabled ones alone.

BUG: 448007
---
 applets/systemtray/qml/ConfigGeneral.qml | 59 +++++++++++++++++++-----
 1 file changed, 48 insertions(+), 11 deletions(-)

diff --git a/applets/systemtray/qml/ConfigGeneral.qml b/applets/systemtray/qml/ConfigGeneral.qml
index 7895a1e414..bd7c7f2f20 100644
--- a/applets/systemtray/qml/ConfigGeneral.qml
+++ b/applets/systemtray/qml/ConfigGeneral.qml
@@ -123,6 +123,37 @@ KCMUtils.ScrollViewKCM {
         }
     }

+    function originalVisibility(itemId: string, isPlasmoid: bool): string {
+        if (cfg_showAllItems || cfg_shownItems.indexOf(itemId) !== -1) {
+            return "shown";
+        } else if (cfg_hiddenItems.indexOf(itemId) !== -1) {
+            return "hidden";
+        } else if ((isPlasmoid && cfg_extraItems.indexOf(itemId) === -1) || (!isPlasmoid && cfg_disabledStatusNotifiers.indexOf(itemId) > -1)) {
+            return "disabled";
+        } else {
+            return "auto";
+        }
+    }
+
+    function setAllVisibilities(visibility: string): void {
+        const model = Plasmoid.configSystemTrayModel;
+        for (let i = 0; i < model.rowCount(); ++i) {
+            const itemId = model.index(i, 0).data(Qt.UserRole + 2);
+            const isPlasmoid = model.index(i, 0).data(Qt.UserRole + 1) === "Plasmoid";
+            const original = originalVisibility(itemId, isPlasmoid);
+            const current = changedVisibility.has(itemId) ? changedVisibility.get(itemId).replace("-sni", "") : original;
+            if (!itemId || current === "disabled") {
+                continue;
+            }
+            if (visibility !== original) {
+                changedVisibility.set(itemId, visibility + (isPlasmoid ? "" : "-sni"));
+            } else {
+                changedVisibility.delete(itemId);
+            }
+        }
+        changedVisibilityChanged();
+    }
+
     function categoryName(category) {
         switch (category) {
         case "ApplicationStatus":
@@ -370,6 +401,22 @@ KCMUtils.ScrollViewKCM {
                         onToggled: showAllCheckBox.toggle()
                     }
                 },
+                Kirigami.Action {
+                    text: i18nc("@action:button opens a menu to change the visibility of all System Tray entries at once", "Set All To")
+                    enabled: !iconsPage.cfg_showAllItems
+                    Kirigami.Action {
+                        text: i18nc("@item:inlistbox Show this System Tray item when relevant", "Show when relevant")
+                        onTriggered: iconsPage.setAllVisibilities("auto")
+                    }
+                    Kirigami.Action {
+                        text: i18nc("@item:inlistbox Always show this System Tray item", "Always show")
+                        onTriggered: iconsPage.setAllVisibilities("shown")
+                    }
+                    Kirigami.Action {
+                        text: i18nc("@item:inlistbox Show this System Tray item only in the expanded popup", "Show only in popup")
+                        onTriggered: iconsPage.setAllVisibilities("hidden")
+                    }
+                },
                 Kirigami.Action {
                     id: searchAction
                     property string searchText: ""
@@ -461,17 +508,7 @@ KCMUtils.ScrollViewKCM {
                     id: visibilityComboBox

                     readonly property string currentVisibility: iconsPage.changedVisibility.has(listItem.itemId) ? iconsPage.changedVisibility.get(listItem.itemId).replace("-sni", "") : originalVisibility
-                    readonly property string originalVisibility: {
-                        if (iconsPage.cfg_showAllItems || iconsPage.cfg_shownItems.indexOf(listItem.itemId) !== -1) {
-                            return "shown";
-                        } else if (iconsPage.cfg_hiddenItems.indexOf(listItem.itemId) !== -1) {
-                            return "hidden";
-                        } else if ((listItem.isPlasmoid && iconsPage.cfg_extraItems.indexOf(listItem.itemId) === -1) || (!listItem.isPlasmoid && iconsPage.cfg_disabledStatusNotifiers.indexOf(listItem.itemId) > -1)) {
-                            return "disabled";
-                        } else {
-                            return "auto";
-                        }
-                    }
+                    readonly property string originalVisibility: iconsPage.originalVisibility(listItem.itemId, listItem.isPlasmoid)

                     implicitContentWidthPolicy: QQC2.ComboBox.WidestText

